package com.finboost.bank.statement.parser.service.document.extraction.nativepdf;

import org.springframework.stereotype.Component;

import java.util.Collections;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

/**
 * Maps bank-format families in the fixture corpus to a native extraction policy.
 * Banks not listed are unsupported for native extraction and use remote ML by default.
 */
@Component
public class NativeBankFormatPolicyRegistry {

    private final Map<String, NativeTableExtractionPolicy> bankPolicies;

    public NativeBankFormatPolicyRegistry() {
        Map<String, NativeTableExtractionPolicy> map = new HashMap<>();

        // Bordered-grid public / PSU style statements
        for (String bank : Set.of(
                "SBI", "PNB", "UNION", "INDIAN", "CBI", "BOB",
                "INDIAN_OVERSEAS", "AHMEDNAGAR", "GS_MAHANAGAR_CO_OP_BANK",
                "TJSB_BANK", "SURYODAY_SMALL_FINANCE_BANK_LTD")) {
            map.put(bank, NativeTableExtractionPolicy.BORDERED_GRID);
        }

        // Box / cell-outline guided retail statements
        for (String bank : Set.of(
                "HDFC", "AXIS", "KOTAK", "IDFC", "YES", "INDUSIND", "IDBI", "BANDHAN")) {
            map.put(bank, NativeTableExtractionPolicy.BOX_GUIDED);
        }

        // Text-aligned, row-selected layouts (often without full ruling grids)
        for (String bank : Set.of(
                "ICICI", "FEDERAL", "STANDARD_CHARTERED", "RBL", "DEUSTCHE",
                "CITI", "MAYBANK", "PUBLIC", "SARASWAT")) {
            map.put(bank, NativeTableExtractionPolicy.TEXT_ALIGNED_ROW_SELECTED);
        }

        this.bankPolicies = Collections.unmodifiableMap(map);
    }

    public Optional<NativeTableExtractionPolicy> resolvePolicy(String bankName) {
        if (bankName == null || bankName.isBlank()) {
            return Optional.empty();
        }
        String key = normalize(bankName);
        NativeTableExtractionPolicy policy = bankPolicies.get(key);
        if (policy != null) {
            return Optional.of(policy);
        }
        // fuzzy match for names like "GS Mahanagar Co-Op Bank"
        for (Map.Entry<String, NativeTableExtractionPolicy> entry : bankPolicies.entrySet()) {
            if (key.contains(entry.getKey()) || entry.getKey().contains(key)) {
                return Optional.of(entry.getValue());
            }
        }
        return Optional.empty();
    }

    public boolean isNativeSupported(String bankName) {
        return resolvePolicy(bankName).isPresent();
    }

    private static String normalize(String bankName) {
        return bankName.trim()
                .toUpperCase(Locale.ROOT)
                .replace('-', '_')
                .replace(' ', '_')
                .replace("__", "_");
    }
}

