/**
 * Offline PDF geometry extraction: words + ruling lines/rectangles in inches (top-left origin).
 */
@Service
@Slf4j
public class NativePdfGeometryService {

    private static final float POINTS_PER_INCH = 72.0f;
    private static final float LINE_AXIS_TOLERANCE = 1.0f;

    public List<NativePdfGeometry> extractGeometry(File pdfFile) throws IOException {
        List<NativePdfGeometry> geometries = new ArrayList<>();
        try (PDDocument document = Loader.loadPDF(pdfFile)) {
            int pageCount = document.getNumberOfPages();
            for (int pageIndex = 0; pageIndex < pageCount; pageIndex++) {
                PDPage page = document.getPage(pageIndex);
                PDRectangle cropBox = page.getCropBox();
                float pageHeightPts = cropBox.getHeight();
                float pageWidthPts = cropBox.getWidth();

                NativePdfGeometry geometry = new NativePdfGeometry();
                geometry.setPageNumber(pageIndex + 1);
                geometry.setWidthInches(pageWidthPts / POINTS_PER_INCH);
                geometry.setHeightInches(pageHeightPts / POINTS_PER_INCH);

                WordCollector wordCollector = new WordCollector(pageHeightPts, pageIndex + 1);
                wordCollector.setStartPage(pageIndex + 1);
                wordCollector.setEndPage(pageIndex + 1);
                wordCollector.getText(document);
                geometry.setWords(wordCollector.getWords());

                try {
                    LineCollector lineCollector = new LineCollector(page, pageHeightPts);
                    lineCollector.processPage(page);
                    geometry.setHorizontalLines(lineCollector.horizontalLines);
                    geometry.setVerticalLines(lineCollector.verticalLines);
                    geometry.setRectangles(lineCollector.rectangles);
                } catch (Exception e) {
                    log.debug("Line extraction failed on page {}: {}", pageIndex + 1, e.getMessage());
                }

                geometries.add(geometry);
            }
        }
        return geometries;
    }

    private static float toInches(float points) {
        return points / POINTS_PER_INCH;
    }

    private static float toTopOriginY(float pdfYBottomOrigin, float pageHeightPts, float heightPts) {
        // PDF y is bottom-left; convert top of glyph to top-left inches
        float topPts = pageHeightPts - (pdfYBottomOrigin + heightPts);
        return toInches(topPts);
    }

    private static class WordCollector extends PDFTextStripper {
        private final float pageHeightPts;
        private final int pageNumber;
        private final List<Word> words = new ArrayList<>();
        private final StringBuilder current = new StringBuilder();
        private final List<TextPosition> currentPositions = new ArrayList<>();

        WordCollector(float pageHeightPts, int pageNumber) throws IOException {
            super();
            this.pageHeightPts = pageHeightPts;
            this.pageNumber = pageNumber;
            setSortByPosition(true);
        }

        List<Word> getWords() {
            flushWord();
            return words;
        }

        @Override
        protected void writeString(String text, List<TextPosition> textPositions) {
            for (TextPosition tp : textPositions) {
                String unicode = tp.getUnicode();
                if (unicode == null || unicode.isEmpty()) {
                    continue;
                }
                if (Character.isWhitespace(unicode.charAt(0))) {
                    flushWord();
                    continue;
                }
                current.append(unicode);
                currentPositions.add(tp);
            }
            flushWord();
        }

        private void flushWord() {
            if (currentPositions.isEmpty()) {
                current.setLength(0);
                return;
            }
            float minX = Float.MAX_VALUE;
            float maxX = Float.MIN_VALUE;
            float minY = Float.MAX_VALUE;
            float maxY = Float.MIN_VALUE;
            for (TextPosition tp : currentPositions) {
                float x = tp.getXDirAdj();
                float yBottom = tp.getYDirAdj() - tp.getHeightDir();
                float w = tp.getWidthDirAdj();
                float h = tp.getHeightDir();
                float top = pageHeightPts - (yBottom + h);
                float left = x;
                float right = x + w;
                float bottom = top + h;
                minX = Math.min(minX, left);
                maxX = Math.max(maxX, right);
                minY = Math.min(minY, top);
                maxY = Math.max(maxY, bottom);
            }
            String content = current.toString().trim();
            current.setLength(0);
            currentPositions.clear();
            if (content.isEmpty()) {
                return;
            }
            float x1 = toInches(minX);
            float y1 = toInches(minY);
            float x2 = toInches(maxX);
            float y2 = toInches(minY);
            float x3 = toInches(maxX);
            float y3 = toInches(maxY);
            float x4 = toInches(minX);
            float y4 = toInches(maxY);
            float width = x2 - x1;
            float height = y3 - y1;
            Word word = new Word(content, x1, y1, x2, y2, x3, y3, x4, y4,
                    pageNumber, width, height, pageNumber, 0);
            words.add(word);
        }
    }

    private static class LineCollector extends PDFGraphicsStreamEngine {
        private final float pageHeightPts;
        private final List<float[]> horizontalLines = new ArrayList<>();
        private final List<float[]> verticalLines = new ArrayList<>();
        private final List<float[]> rectangles = new ArrayList<>();
        private float cx;
        private float cy;
        private final List<float[]> pathPoints = new ArrayList<>();

        protected LineCollector(PDPage page, float pageHeightPts) {
            super(page);
            this.pageHeightPts = pageHeightPts;
        }

        private float[] toTopInchesLine(float x1, float y1, float x2, float y2) {
            // store as [minX, maxX, y] or [x, minY, maxY] in inches top-left
            float ix1 = toInches(x1);
            float ix2 = toInches(x2);
            float iy1 = toInches(pageHeightPts - y1);
            float iy2 = toInches(pageHeightPts - y2);
            return new float[]{ix1, iy1, ix2, iy2};
        }

        @Override
        public void appendRectangle(Point2D p0, Point2D p1, Point2D p2, Point2D p3) {
            float minX = (float) Math.min(Math.min(p0.getX(), p1.getX()), Math.min(p2.getX(), p3.getX()));
            float maxX = (float) Math.max(Math.max(p0.getX(), p1.getX()), Math.max(p2.getX(), p3.getX()));
            float minYPdf = (float) Math.min(Math.min(p0.getY(), p1.getY()), Math.min(p2.getY(), p3.getY()));
            float maxYPdf = (float) Math.max(Math.max(p0.getY(), p1.getY()), Math.max(p2.getY(), p3.getY()));
            float top = toInches(pageHeightPts - maxYPdf);
            float bottom = toInches(pageHeightPts - minYPdf);
            float left = toInches(minX);
            float right = toInches(maxX);
            if (right - left > 0.05f && bottom - top > 0.05f) {
                rectangles.add(new float[]{left, top, right, bottom});
            }
        }

        @Override
        public void clip(int windingRule) {
        }

        @Override
        public void moveTo(float x, float y) {
            cx = x;
            cy = y;
            pathPoints.clear();
            pathPoints.add(new float[]{x, y});
        }

        @Override
        public void lineTo(float x, float y) {
            recordSegment(cx, cy, x, y);
            cx = x;
            cy = y;
            pathPoints.add(new float[]{x, y});
        }

        @Override
        public void curveTo(float x1, float y1, float x2, float y2, float x3, float y3) {
            cx = x3;
            cy = y3;
            pathPoints.add(new float[]{x3, y3});
        }

        @Override
        public Point2D getCurrentPoint() {
            return new Point2D.Float(cx, cy);
        }

        @Override
        public void closePath() {
            if (pathPoints.size() >= 2) {
                float[] first = pathPoints.get(0);
                recordSegment(cx, cy, first[0], first[1]);
            }
        }

        @Override
        public void endPath() {
            pathPoints.clear();
        }

        @Override
        public void strokePath() {
            pathPoints.clear();
        }

        @Override
        public void fillPath(int windingRule) {
            pathPoints.clear();
        }

        @Override
        public void fillAndStrokePath(int windingRule) {
            pathPoints.clear();
        }

        @Override
        public void shadingFill(COSName shadingName) {
        }

        @Override
        public void drawImage(PDImage pdImage) {
        }

        private void recordSegment(float x1, float y1, float x2, float y2) {
            float[] line = toTopInchesLine(x1, y1, x2, y2);
            float dx = Math.abs(line[2] - line[0]);
            float dy = Math.abs(line[3] - line[1]);
            if (dy < toInches(LINE_AXIS_TOLERANCE) && dx > 0.15f) {
                float y = (line[1] + line[3]) / 2f;
                horizontalLines.add(new float[]{Math.min(line[0], line[2]), Math.max(line[0], line[2]), y});
            } else if (dx < toInches(LINE_AXIS_TOLERANCE) && dy > 0.15f) {
                float x = (line[0] + line[2]) / 2f;
                verticalLines.add(new float[]{x, Math.min(line[1], line[3]), Math.max(line[1], line[3])});
            }
        }
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativepdf.policy;

import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.service.document.extraction.nativepdf.NativePdfGeometry;

import java.util.List;

public interface NativeTableExtractionStrategy {
    List<Table> extractTables(NativePdfGeometry geometry);
}

package com.finboost.bank.statement.parser.service.document.extraction.nativepdf;

import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.TableCell;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

public final class NativeTableBuilder {

    private static final Pattern DATE_PATTERN = Pattern.compile(
            ".*(\\d{1,2}[-/]\\d{1,2}[-/]\\d{2,4}|\\d{1,2}[-/][A-Za-z]{3}[-/]\\d{2,4}|\\d{1,2}\\s+[A-Za-z]{3}\\s+\\d{2,4}).*"
    );

    private NativeTableBuilder() {
    }

    public static Table buildTable(int pageNumber, List<List<List<Word>>> rows) {
        if (rows == null || rows.isEmpty()) {
            return null;
        }
        int colCount = rows.stream().mapToInt(List::size).max().orElse(0);
        if (colCount == 0) {
            return null;
        }

        Map<Integer, Map<Integer, TableCell>> cells = new LinkedHashMap<>();
        float minX = Float.MAX_VALUE, minY = Float.MAX_VALUE, maxX = Float.MIN_VALUE, maxY = Float.MIN_VALUE;
        int rowIndex = 0;
        for (List<List<Word>> row : rows) {
            Map<Integer, TableCell> rowMap = new LinkedHashMap<>();
            for (int c = 0; c < colCount; c++) {
                List<Word> cellWords = c < row.size() ? row.get(c) : List.of();
                TableCell cell = createCell(rowIndex, c, cellWords);
                rowMap.put(c, cell);
                if (cell.getX1() != null) {
                    minX = Math.min(minX, cell.getX1());
                    minY = Math.min(minY, cell.getY1());
                    maxX = Math.max(maxX, cell.getX3());
                    maxY = Math.max(maxY, cell.getY3());
                }
            }
            cells.put(rowIndex, rowMap);
            rowIndex++;
        }

        if (minX == Float.MAX_VALUE) {
            minX = 0;
            minY = 0;
            maxX = 1;
            maxY = 1;
        }

        Table table = new Table();
        table.setPageNumber(pageNumber);
        table.setX1(minX);
        table.setY1(minY);
        table.setX2(maxX);
        table.setY2(minY);
        table.setX3(maxX);
        table.setY3(maxY);
        table.setX4(minX);
        table.setY4(maxY);
        table.setTotalRows(rows.size());
        table.setTotalColumns(colCount);
        table.setCells(cells);
        table.setColType(new ArrayList<>());
        table.setTxnColType(new ArrayList<>());
        table.setBankTransactions(false);
        return table;
    }

    public static TableCell createCell(int rowIndex, int colIndex, List<Word> words) {
        TableCell cell = new TableCell();
        cell.setRowindex(rowIndex);
        cell.setColindex(colIndex);
        cell.setRowspan(1);
        cell.setColspan(1);
        List<Word> safeWords = words == null ? new ArrayList<>() : new ArrayList<>(words);
        safeWords.sort(Comparator.comparing(Word::getActualY1).thenComparing(Word::getActualX1));
        cell.setWords(safeWords);
        if (safeWords.isEmpty()) {
            cell.setX1(0f);
            cell.setY1(0f);
            cell.setX2(0f);
            cell.setY2(0f);
            cell.setX3(0f);
            cell.setY3(0f);
            cell.setX4(0f);
            cell.setY4(0f);
            return cell;
        }
        float minX = safeWords.stream().map(Word::getActualX1).min(Float::compare).orElse(0f);
        float maxX = safeWords.stream().map(w -> w.getX2() != null ? w.getX2() : w.getActualX1()).max(Float::compare).orElse(0f);
        float minY = safeWords.stream().map(Word::getActualY1).min(Float::compare).orElse(0f);
        float maxY = safeWords.stream().map(w -> w.getY3() != null ? w.getY3() : w.getActualY1()).max(Float::compare).orElse(0f);
        cell.setX1(minX);
        cell.setY1(minY);
        cell.setX2(maxX);
        cell.setY2(minY);
        cell.setX3(maxX);
        cell.setY3(maxY);
        cell.setX4(minX);
        cell.setY4(maxY);
        return cell;
    }

    public static boolean looksLikeTransactionTable(Table table) {
        if (table == null || table.getCells() == null || table.getCells().size() < 2) {
            return false;
        }
        if (table.getTotalColumns() == null || table.getTotalColumns() < 3) {
            return false;
        }
        int dateLikeRows = 0;
        for (Map<Integer, TableCell> row : table.getCells().values()) {
            String content = row.values().stream()
                    .map(TableCell::getContent)
                    .filter(s -> s != null && !s.isBlank())
                    .collect(Collectors.joining(" "));
            if (DATE_PATTERN.matcher(content).matches()) {
                dateLikeRows++;
            }
        }
        return dateLikeRows >= 1;
    }

    public static List<List<Word>> clusterWordsIntoLines(List<Word> words, float yTolerance) {
        List<Word> sorted = words.stream()
                .sorted(Comparator.comparing(Word::getActualY1).thenComparing(Word::getActualX1))
                .collect(Collectors.toList());
        List<List<Word>> lines = new ArrayList<>();
        for (Word word : sorted) {
            if (lines.isEmpty()) {
                List<Word> line = new ArrayList<>();
                line.add(word);
                lines.add(line);
                continue;
            }
            List<Word> last = lines.get(lines.size() - 1);
            float lastY = last.stream().map(Word::getActualY1).reduce(0f, Float::sum) / last.size();
            if (Math.abs(word.getActualY1() - lastY) <= yTolerance) {
                last.add(word);
            } else {
                List<Word> line = new ArrayList<>();
                line.add(word);
                lines.add(line);
            }
        }
        for (List<Word> line : lines) {
            line.sort(Comparator.comparing(Word::getActualX1));
        }
        return lines;
    }

    public static List<Float> detectColumnBoundaries(List<Word> words, float pageWidth) {
        if (words == null || words.isEmpty()) {
            return List.of(0f, pageWidth);
        }
        int bins = 100;
        int[] hist = new int[bins];
        float minX = words.stream().map(Word::getActualX1).min(Float::compare).orElse(0f);
        float maxX = words.stream().map(w -> w.getX2() != null ? w.getX2() : w.getActualX1()).max(Float::compare).orElse(pageWidth);
        if (maxX - minX < 0.1f) {
            return List.of(minX, maxX);
        }
        for (Word w : words) {
            float cx = (w.getActualX1() + (w.getX2() != null ? w.getX2() : w.getActualX1())) / 2f;
            int idx = (int) ((cx - minX) / (maxX - minX) * (bins - 1));
            idx = Math.max(0, Math.min(bins - 1, idx));
            hist[idx]++;
        }
        int max = 0;
        for (int v : hist) max = Math.max(max, v);
        float threshold = Math.max(1, max * 0.08f);

        List<Float> valleys = new ArrayList<>();
        valleys.add(minX);
        boolean inValley = false;
        int valleyStart = 0;
        for (int i = 1; i < bins - 1; i++) {
            if (hist[i] <= threshold) {
                if (!inValley) {
                    inValley = true;
                    valleyStart = i;
                }
            } else if (inValley) {
                int mid = (valleyStart + i) / 2;
                float x = minX + (maxX - minX) * mid / (bins - 1f);
                if (x - valleys.get(valleys.size() - 1) > 0.25f) {
                    valleys.add(x);
                }
                inValley = false;
            }
        }
        if (maxX - valleys.get(valleys.size() - 1) > 0.1f) {
            valleys.add(maxX);
        }
        if (valleys.size() < 3) {
            // fallback equal-ish split into 4 columns common for statements
            valleys.clear();
            valleys.add(minX);
            valleys.add(minX + (maxX - minX) * 0.18f);
            valleys.add(minX + (maxX - minX) * 0.55f);
            valleys.add(minX + (maxX - minX) * 0.75f);
            valleys.add(maxX);
        }
        return valleys;
    }

    public static List<List<Word>> assignWordsToColumns(List<Word> lineWords, List<Float> boundaries) {
        int cols = Math.max(1, boundaries.size() - 1);
        List<List<Word>> cells = new ArrayList<>();
        for (int i = 0; i < cols; i++) {
            cells.add(new ArrayList<>());
        }
        for (Word w : lineWords) {
            float cx = (w.getActualX1() + (w.getX2() != null ? w.getX2() : w.getActualX1())) / 2f;
            int col = cols - 1;
            for (int i = 0; i < cols; i++) {
                float left = boundaries.get(i);
                float right = boundaries.get(i + 1);
                if (cx >= left && cx <= right + 0.001f) {
                    col = i;
                    break;
                }
            }
            cells.get(col).add(w);
        }
        return cells;
    }

    public static List<Float> clusterPositions(List<Float> values, float tolerance) {
        if (values == null || values.isEmpty()) {
            return List.of();
        }
        List<Float> sorted = values.stream().sorted().collect(Collectors.toList());
        List<Float> clusters = new ArrayList<>();
        float sum = sorted.get(0);
        int count = 1;
        float start = sorted.get(0);
        for (int i = 1; i < sorted.size(); i++) {
            if (sorted.get(i) - start <= tolerance) {
                sum += sorted.get(i);
                count++;
            } else {
                clusters.add(sum / count);
                sum = sorted.get(i);
                count = 1;
                start = sorted.get(i);
            }
        }
        clusters.add(sum / count);
        return clusters;
    }

    public static boolean lineLooksLikeTransaction(List<Word> line) {
        String content = line.stream().map(Word::getContent).collect(Collectors.joining(" "));
        return DATE_PATTERN.matcher(content).matches();
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativepdf.policy;

import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.service.document.extraction.nativepdf.NativePdfGeometry;
import com.finboost.bank.statement.parser.service.document.extraction.nativepdf.NativeTableBuilder;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;

/**
 * Builds tables from explicit horizontal/vertical ruling lines (bordered grids).
 */
@Component
public class BorderedGridTableExtractor implements NativeTableExtractionStrategy {

    @Override
    public List<Table> extractTables(NativePdfGeometry geometry) {
        List<Table> tables = new ArrayList<>();
        if (geometry.getWords() == null || geometry.getWords().isEmpty()) {
            return tables;
        }

        List<Float> hYs = NativeTableBuilder.clusterPositions(
                geometry.getHorizontalLines().stream().map(l -> l[2]).collect(Collectors.toList()),
                0.02f);
        List<Float> vXs = NativeTableBuilder.clusterPositions(
                geometry.getVerticalLines().stream().map(l -> l[0]).collect(Collectors.toList()),
                0.02f);

        if (hYs.size() < 3 || vXs.size() < 3) {
            return tables;
        }

        hYs.sort(Float::compare);
        vXs.sort(Float::compare);

        // Prefer the densest contiguous grid band (transaction block)
        int bestStart = 0;
        int bestEnd = hYs.size() - 1;
        int bestScore = -1;
        for (int i = 0; i < hYs.size(); i++) {
            for (int j = i + 2; j < hYs.size(); j++) {
                float top = hYs.get(i);
                float bottom = hYs.get(j);
                long wordCount = geometry.getWords().stream()
                        .filter(w -> w.getActualY1() >= top - 0.02f && w.getActualY1() <= bottom + 0.02f)
                        .count();
                int score = (int) wordCount + (j - i) * 2;
                if (score > bestScore) {
                    bestScore = score;
                    bestStart = i;
                    bestEnd = j;
                }
            }
        }

        List<Float> rowBounds = hYs.subList(bestStart, bestEnd + 1);
        if (rowBounds.size() < 3) {
            return tables;
        }

        float tableTop = rowBounds.get(0);
        float tableBottom = rowBounds.get(rowBounds.size() - 1);
        float tableLeft = vXs.get(0);
        float tableRight = vXs.get(vXs.size() - 1);

        List<Word> tableWords = geometry.getWords().stream()
                .filter(w -> {
                    float cx = (w.getActualX1() + (w.getX2() != null ? w.getX2() : w.getActualX1())) / 2f;
                    float cy = w.getActualY1();
                    return cx >= tableLeft - 0.05f && cx <= tableRight + 0.05f
                            && cy >= tableTop - 0.05f && cy <= tableBottom + 0.05f;
                })
                .sorted(Comparator.comparing(Word::getActualY1).thenComparing(Word::getActualX1))
                .collect(Collectors.toList());

        List<List<List<Word>>> rows = new ArrayList<>();
        for (int r = 0; r < rowBounds.size() - 1; r++) {
            float top = rowBounds.get(r);
            float bottom = rowBounds.get(r + 1);
            if (bottom - top < 0.05f) {
                continue;
            }
            List<Word> rowWords = tableWords.stream()
                    .filter(w -> {
                        float cy = w.getActualY1() + (w.getHeight() != null ? w.getHeight() / 2f : 0.05f);
                        return cy >= top && cy < bottom;
                    })
                    .collect(Collectors.toList());
            if (rowWords.isEmpty()) {
                continue;
            }
            List<List<Word>> cols = new ArrayList<>();
            for (int c = 0; c < vXs.size() - 1; c++) {
                float left = vXs.get(c);
                float right = vXs.get(c + 1);
                List<Word> cellWords = rowWords.stream()
                        .filter(w -> {
                            float cx = (w.getActualX1() + (w.getX2() != null ? w.getX2() : w.getActualX1())) / 2f;
                            return cx >= left && cx < right + 0.001f;
                        })
                        .collect(Collectors.toList());
                cols.add(cellWords);
            }
            rows.add(cols);
        }

        Table table = NativeTableBuilder.buildTable(geometry.getPageNumber(), rows);
        if (table != null) {
            tables.add(table);
        }
        return tables;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativepdf.policy;

import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.service.document.extraction.nativepdf.NativePdfGeometry;
import com.finboost.bank.statement.parser.service.document.extraction.nativepdf.NativeTableBuilder;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;

/**
 * Uses drawn rectangles / row boxes as guides, then splits columns by text alignment.
 */
@Component
public class BoxGuidedTableExtractor implements NativeTableExtractionStrategy {

    @Override
    public List<Table> extractTables(NativePdfGeometry geometry) {
        List<Table> tables = new ArrayList<>();
        if (geometry.getWords() == null || geometry.getWords().isEmpty()) {
            return tables;
        }

        List<float[]> boxes = geometry.getRectangles().stream()
                .filter(r -> (r[2] - r[0]) > geometry.getWidthInches() * 0.35f)
                .filter(r -> (r[3] - r[1]) > 0.12f && (r[3] - r[1]) < 1.5f)
                .sorted(Comparator.comparing(r -> r[1]))
                .collect(Collectors.toList());

        // Fall back to horizontal line bands if few boxes
        if (boxes.size() < 3) {
            List<Float> hYs = NativeTableBuilder.clusterPositions(
                    geometry.getHorizontalLines().stream().map(l -> l[2]).collect(Collectors.toList()),
                    0.025f);
            hYs.sort(Float::compare);
            boxes = new ArrayList<>();
            for (int i = 0; i < hYs.size() - 1; i++) {
                float top = hYs.get(i);
                float bottom = hYs.get(i + 1);
                if (bottom - top < 0.08f || bottom - top > 1.2f) {
                    continue;
                }
                boxes.add(new float[]{0.3f, top, geometry.getWidthInches() - 0.3f, bottom});
            }
        }

        if (boxes.size() < 2) {
            return tables;
        }

        // Keep the longest contiguous sequence of similarly-wide boxes
        List<float[]> rowBoxes = selectTransactionBoxBand(boxes);
        if (rowBoxes.size() < 2) {
            return tables;
        }

        float left = rowBoxes.stream().map(b -> b[0]).min(Float::compare).orElse(0f);
        float right = rowBoxes.stream().map(b -> b[2]).max(Float::compare).orElse(geometry.getWidthInches());
        float top = rowBoxes.get(0)[1];
        float bottom = rowBoxes.get(rowBoxes.size() - 1)[3];

        List<Word> regionWords = geometry.getWords().stream()
                .filter(w -> {
                    float cx = (w.getActualX1() + (w.getX2() != null ? w.getX2() : w.getActualX1())) / 2f;
                    float cy = w.getActualY1();
                    return cx >= left - 0.1f && cx <= right + 0.1f && cy >= top - 0.05f && cy <= bottom + 0.05f;
                })
                .collect(Collectors.toList());

        List<Float> boundaries = NativeTableBuilder.detectColumnBoundaries(regionWords, geometry.getWidthInches());
        List<List<List<Word>>> rows = new ArrayList<>();
        for (float[] box : rowBoxes) {
            List<Word> rowWords = regionWords.stream()
                    .filter(w -> {
                        float cy = w.getActualY1() + (w.getHeight() != null ? w.getHeight() / 2f : 0.04f);
                        return cy >= box[1] && cy <= box[3];
                    })
                    .sorted(Comparator.comparing(Word::getActualX1))
                    .collect(Collectors.toList());
            if (rowWords.isEmpty()) {
                continue;
            }
            rows.add(NativeTableBuilder.assignWordsToColumns(rowWords, boundaries));
        }

        Table table = NativeTableBuilder.buildTable(geometry.getPageNumber(), rows);
        if (table != null) {
            tables.add(table);
        }
        return tables;
    }

    private List<float[]> selectTransactionBoxBand(List<float[]> boxes) {
        if (boxes.isEmpty()) {
            return boxes;
        }
        // Choose the largest run of boxes with similar left/right edges
        int bestStart = 0;
        int bestLen = 1;
        int curStart = 0;
        for (int i = 1; i < boxes.size(); i++) {
            float[] prev = boxes.get(i - 1);
            float[] cur = boxes.get(i);
            boolean aligned = Math.abs(prev[0] - cur[0]) < 0.35f && Math.abs(prev[2] - cur[2]) < 0.35f;
            boolean close = cur[1] - prev[3] < 0.35f;
            if (aligned && close) {
                int len = i - curStart + 1;
                if (len > bestLen) {
                    bestLen = len;
                    bestStart = curStart;
                }
            } else {
                curStart = i;
            }
        }
        return new ArrayList<>(boxes.subList(bestStart, bestStart + bestLen));
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativepdf.policy;

import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.service.document.extraction.nativepdf.NativePdfGeometry;
import com.finboost.bank.statement.parser.service.document.extraction.nativepdf.NativeTableBuilder;
import org.springframework.stereotype.Component;

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

/**
 * Text-aligned layout: cluster lines by Y, detect columns by X histogram,
 * and keep contiguous row bands that look like transaction rows.
 */
@Component
public class TextAlignedRowSelectedTableExtractor implements NativeTableExtractionStrategy {

    private static final float LINE_Y_TOLERANCE = 0.045f;

    @Override
    public List<Table> extractTables(NativePdfGeometry geometry) {
        List<Table> tables = new ArrayList<>();
        if (geometry.getWords() == null || geometry.getWords().isEmpty()) {
            return tables;
        }

        List<List<Word>> lines = NativeTableBuilder.clusterWordsIntoLines(geometry.getWords(), LINE_Y_TOLERANCE);
        if (lines.size() < 3) {
            return tables;
        }

        // Mark transaction-like lines and select the longest contiguous band
        boolean[] isTxn = new boolean[lines.size()];
        for (int i = 0; i < lines.size(); i++) {
            isTxn[i] = NativeTableBuilder.lineLooksLikeTransaction(lines.get(i));
        }

        int bestStart = -1;
        int bestEnd = -1;
        int bestScore = 0;
        int i = 0;
        while (i < lines.size()) {
            if (!isTxn[i]) {
                i++;
                continue;
            }
            int start = i;
            int txnCount = 0;
            while (i < lines.size()) {
                // allow short non-date continuation lines inside a multi-line description
                if (isTxn[i] || (i > start && i + 1 < lines.size() && isTxn[i + 1] && lines.get(i).size() <= 8)) {
                    if (isTxn[i]) {
                        txnCount++;
                    }
                    i++;
                } else {
                    break;
                }
            }
            int end = i - 1;
            // expand one header line above if present
            int expandedStart = start > 0 ? start - 1 : start;
            int score = txnCount * 10 + (end - expandedStart + 1);
            if (score > bestScore && txnCount >= 1) {
                bestScore = score;
                bestStart = expandedStart;
                bestEnd = end;
            }
        }

        if (bestStart < 0) {
            // No date rows found - take densest middle band of lines
            bestStart = Math.max(0, lines.size() / 5);
            bestEnd = Math.min(lines.size() - 1, lines.size() * 4 / 5);
            if (bestEnd - bestStart < 2) {
                return tables;
            }
        }

        List<List<Word>> selected = lines.subList(bestStart, bestEnd + 1);
        List<Word> bandWords = selected.stream().flatMap(List::stream).collect(Collectors.toList());
        List<Float> boundaries = NativeTableBuilder.detectColumnBoundaries(bandWords, geometry.getWidthInches());

        List<List<List<Word>>> rows = new ArrayList<>();
        for (List<Word> line : selected) {
            if (line.isEmpty()) {
                continue;
            }
            rows.add(NativeTableBuilder.assignWordsToColumns(line, boundaries));
        }

        // Merge continuation lines without a date into previous row (description wrap)
        rows = mergeContinuationRows(rows);

        Table table = NativeTableBuilder.buildTable(geometry.getPageNumber(), rows);
        if (table != null) {
            tables.add(table);
        }
        return tables;
    }

    private List<List<List<Word>>> mergeContinuationRows(List<List<List<Word>>> rows) {
        if (rows.isEmpty()) {
            return rows;
        }
        List<List<List<Word>>> merged = new ArrayList<>();
        for (List<List<Word>> row : rows) {
            List<Word> flat = row.stream().flatMap(List::stream).collect(Collectors.toList());
            boolean hasDate = NativeTableBuilder.lineLooksLikeTransaction(flat);
            if (!merged.isEmpty() && !hasDate) {
                List<List<Word>> prev = merged.get(merged.size() - 1);
                for (int c = 0; c < Math.min(prev.size(), row.size()); c++) {
                    prev.get(c).addAll(row.get(c));
                }
            } else {
                merged.add(row);
            }
        }
        return merged;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativepdf;

import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionRequest;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.representation.document.extraction.ExtractionPath;
import com.finboost.bank.statement.parser.representation.document.extraction.Page;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.service.document.extraction.azure.AzureDocumentIntelligenceResponseMapper;
import com.finboost.bank.statement.parser.service.document.extraction.nativepdf.policy.BorderedGridTableExtractor;
import com.finboost.bank.statement.parser.service.document.extraction.nativepdf.policy.BoxGuidedTableExtractor;
import com.finboost.bank.statement.parser.service.document.extraction.nativepdf.policy.NativeTableExtractionStrategy;
import com.finboost.bank.statement.parser.service.document.extraction.nativepdf.policy.TextAlignedRowSelectedTableExtractor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.stream.Collectors;

/**
 * Offline native transaction-table extraction for supported bank-format families.
 */
@Service
@Slf4j
public class NativeDocumentExtractionService {

    private final NativeBankFormatPolicyRegistry policyRegistry;
    private final NativePdfGeometryService geometryService;
    private final BorderedGridTableExtractor borderedGridTableExtractor;
    private final BoxGuidedTableExtractor boxGuidedTableExtractor;
    private final TextAlignedRowSelectedTableExtractor textAlignedRowSelectedTableExtractor;
    private final AzureDocumentIntelligenceResponseMapper wordIndexAssigner;

    @Autowired
    public NativeDocumentExtractionService(
            NativeBankFormatPolicyRegistry policyRegistry,
            NativePdfGeometryService geometryService,
            BorderedGridTableExtractor borderedGridTableExtractor,
            BoxGuidedTableExtractor boxGuidedTableExtractor,
            TextAlignedRowSelectedTableExtractor textAlignedRowSelectedTableExtractor,
            AzureDocumentIntelligenceResponseMapper wordIndexAssigner) {
        this.policyRegistry = policyRegistry;
        this.geometryService = geometryService;
        this.borderedGridTableExtractor = borderedGridTableExtractor;
        this.boxGuidedTableExtractor = boxGuidedTableExtractor;
        this.textAlignedRowSelectedTableExtractor = textAlignedRowSelectedTableExtractor;
        this.wordIndexAssigner = wordIndexAssigner;
    }

    public Optional<NativeTableExtractionPolicy> resolvePolicy(String bankName) {
        return policyRegistry.resolvePolicy(bankName);
    }

    /**
     * Attempts native extraction for the request's bank family.
     * Returns empty when bank is unsupported or native layout extraction fails quality checks.
     */
    public Optional<DocumentExtractionResult> tryExtract(DocumentExtractionRequest request) throws IOException {
        if (request == null || request.getStatementFile() == null) {
            return Optional.empty();
        }
        Optional<NativeTableExtractionPolicy> policyOpt = policyRegistry.resolvePolicy(request.getBankName());
        if (policyOpt.isEmpty()) {
            log.info("No native policy for bank {}; using remote ML default", request.getBankName());
            return Optional.empty();
        }
        NativeTableExtractionPolicy policy = policyOpt.get();
        NativeTableExtractionStrategy strategy = strategyFor(policy);

        List<NativePdfGeometry> geometries = geometryService.extractGeometry(request.getStatementFile());
        if (geometries.isEmpty()) {
            return Optional.empty();
        }

        DocumentExtractionResult result = new DocumentExtractionResult();
        Map<Integer, Page> pages = new HashMap<>();
        int txnTablePages = 0;

        for (NativePdfGeometry geometry : geometries) {
            Page page = new Page();
            page.setPageNumber(geometry.getPageNumber());
            page.setWidth((double) geometry.getWidthInches());
            page.setHeight((double) geometry.getHeightInches());
            page.setWords(geometry.getWords());
            page.setContent(geometry.getWords().stream().map(Word::getContent).collect(Collectors.joining(" ")));

            List<Table> extracted = strategy.extractTables(geometry);
            Map<Integer, Table> tables = new LinkedHashMap<>();
            int idx = 0;
            boolean pageHasTxn = false;
            for (Table table : extracted) {
                if (NativeTableBuilder.looksLikeTransactionTable(table)) {
                    pageHasTxn = true;
                }
                tables.put(idx++, table);
            }
            if (pageHasTxn) {
                txnTablePages++;
            }
            page.setTables(tables);
            pages.put(geometry.getPageNumber(), page);
        }

        result.setPages(pages);
        result.setNoOfPages(pages.size());
        result.setExtractionPath(ExtractionPath.NATIVE);
        result.setNativePolicy(policy);
        wordIndexAssigner.assignWordIndices(result);

        if (!isSuccessfulNativeResult(result, txnTablePages)) {
            log.info("Native {} extraction did not meet success criteria for bank {}",
                    policy, request.getBankName());
            return Optional.empty();
        }

        log.info("Native {} extraction succeeded for bank {}", policy, request.getBankName());
        return Optional.of(result);
    }

    private NativeTableExtractionStrategy strategyFor(NativeTableExtractionPolicy policy) {
        return switch (policy) {
            case BORDERED_GRID -> borderedGridTableExtractor;
            case BOX_GUIDED -> boxGuidedTableExtractor;
            case TEXT_ALIGNED_ROW_SELECTED -> textAlignedRowSelectedTableExtractor;
        };
    }

    private boolean isSuccessfulNativeResult(DocumentExtractionResult result, int txnTablePages) {
        if (result.getPages() == null || result.getPages().isEmpty()) {
            return false;
        }
        int tableCount = result.getPages().values().stream()
                .mapToInt(p -> p.getTables() == null ? 0 : p.getTables().size())
                .sum();
        if (tableCount == 0) {
            return false;
        }
        // At least one page should yield a transaction-like table
        return txnTablePages > 0;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction;

import com.finboost.bank.statement.parser.representation.bankstatement.BankStatementVO;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionRequest;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.representation.document.extraction.ExtractionPath;
import com.finboost.bank.statement.parser.service.document.extraction.azure.AzureDocumentExtractionServiceImpl;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankStatementProcessorImpl;
import com.finboost.bank.statement.parser.service.document.extraction.nativepdf.NativeDocumentExtractionService;
import com.finboost.bank.statement.parser.service.document.extraction.nativepdf.NativeTableExtractionPolicy;
import com.finboost.bank.statement.parser.service.document.extraction.IBankSpecificParsingService;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.AnalyzeDocuments;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.EPdfCharacterExtractionService;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Primary;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.util.Optional;

/**
 * Routes document extraction through offline native table policies when supported,
 * otherwise (or on native failure) uses the remote ML path.
 */
@Service
@Primary
@Slf4j
public class HybridDocumentExtractionService implements DocumentExtractionService {

    private final NativeDocumentExtractionService nativeDocumentExtractionService;
    private final AzureDocumentExtractionServiceImpl azureDocumentExtractionService;
    private final EPdfCharacterExtractionService ePdfCharacterExtractionService;
    private final IBankSpecificParsingService bankSpecificParsingService;
    private final AnalyzeDocuments analyzeDocuments;

    @Autowired
    public HybridDocumentExtractionService(
            NativeDocumentExtractionService nativeDocumentExtractionService,
            AzureDocumentExtractionServiceImpl azureDocumentExtractionService,
            EPdfCharacterExtractionService ePdfCharacterExtractionService,
            IBankSpecificParsingService bankSpecificParsingService,
            AnalyzeDocuments analyzeDocuments) {
        this.nativeDocumentExtractionService = nativeDocumentExtractionService;
        this.azureDocumentExtractionService = azureDocumentExtractionService;
        this.ePdfCharacterExtractionService = ePdfCharacterExtractionService;
        this.bankSpecificParsingService = bankSpecificParsingService;
        this.analyzeDocuments = analyzeDocuments;
    }

    @Override
    public DocumentExtractionResult extractDocument(BankStatementVO bankStatementVO) throws IOException {
        DocumentExtractionRequest documentExtractionRequest = new DocumentExtractionRequest();
        documentExtractionRequest.setStatementFile(bankStatementVO.getDecryptedFile());
        documentExtractionRequest.setBankName(bankStatementVO.getBank());
        try {
            documentExtractionRequest.setStatementFromDate(
                    BankStatementProcessorImpl.parseDate(bankStatementVO.getBankAccountDetailsVO().getStatementFrom()));
        } catch (Exception e) {
            log.warn("Failed to parse statement-from-date from date string {}",
                    bankStatementVO.getBankAccountDetailsVO() != null
                            ? bankStatementVO.getBankAccountDetailsVO().getStatementFrom() : null);
        }
        DocumentExtractionResult result = extractDocument(documentExtractionRequest);
        if (result != null && result.getExtractionPath() != null) {
            bankStatementVO.setExtractionPath(result.getExtractionPath());
            bankStatementVO.setNativePolicy(result.getNativePolicy());
        }
        return result;
    }

    @Override
    public DocumentExtractionResult extractDocument(DocumentExtractionRequest request) throws IOException {
        Optional<NativeTableExtractionPolicy> policy =
                nativeDocumentExtractionService.resolvePolicy(request.getBankName());

        if (policy.isPresent()) {
            try {
                Optional<DocumentExtractionResult> nativeResult = nativeDocumentExtractionService.tryExtract(request);
                if (nativeResult.isPresent()) {
                    return finalizeNativeResult(nativeResult.get(), request);
                }
                log.info("Native extraction failed for bank {}; falling back to remote ML", request.getBankName());
                DocumentExtractionResult mlResult = azureDocumentExtractionService.extractDocument(request);
                annotatePath(mlResult, ExtractionPath.NATIVE_TO_ML_FALLBACK, policy.get());
                return mlResult;
            } catch (Exception e) {
                log.warn("Native extraction error for bank {}: {}; falling back to remote ML",
                        request.getBankName(), e.getMessage());
                DocumentExtractionResult mlResult = azureDocumentExtractionService.extractDocument(request);
                annotatePath(mlResult, ExtractionPath.NATIVE_TO_ML_FALLBACK, policy.get());
                return mlResult;
            }
        }

        DocumentExtractionResult mlResult = azureDocumentExtractionService.extractDocument(request);
        annotatePath(mlResult, ExtractionPath.ML, null);
        return mlResult;
    }

    private DocumentExtractionResult finalizeNativeResult(
            DocumentExtractionResult result, DocumentExtractionRequest request) throws IOException {
        try {
            ePdfCharacterExtractionService.enhanceDocumentWithCharacterInfo(result, request.getStatementFile());
        } catch (Exception e) {
            log.warn("Failed to enhance native result with character info: {}", e.getMessage());
        }

        bankSpecificParsingService.identifyBankSpecificStatementProcess(result, request);
        if (result.isSkipFurtherProcessing()) {
            result.setExtractionPath(ExtractionPath.NATIVE);
            return result;
        }

        DocumentExtractionResult preProcessedResultByHeader =
                analyzeDocuments.preProcessForVerificationByHeader(result, 5);
        if (preProcessedResultByHeader != null && preProcessedResultByHeader.getPreProcessVerificationResult() != null) {
            result.setPreProcessVerificationResult(preProcessedResultByHeader.getPreProcessVerificationResult());
        } else {
            DocumentExtractionResult preprocessedResult =
                    analyzeDocuments.preProcessForVerification(result, result.getNoOfPages());
            if (preprocessedResult != null && preprocessedResult.getPreProcessVerificationResult() != null) {
                result.setPreProcessVerificationResult(preprocessedResult.getPreProcessVerificationResult());
            }
        }
        analyzeDocuments.analyzeDocument(result, true, true, true);
        result.setExtractionPath(ExtractionPath.NATIVE);
        return result;
    }

    private void annotatePath(DocumentExtractionResult result, ExtractionPath path, NativeTableExtractionPolicy policy) {
        if (result == null) {
            return;
        }
        if (result.getExtractionPath() == null) {
            result.setExtractionPath(path);
        } else if (path == ExtractionPath.NATIVE_TO_ML_FALLBACK) {
            result.setExtractionPath(path);
        }
        if (result.getNativePolicy() == null && policy != null) {
            result.setNativePolicy(policy);
        }
    }
}

package com.finboost.bank.statement.parser.representation.document.extraction;

import com.finboost.bank.statement.parser.service.document.extraction.nativepdf.NativeTableExtractionPolicy;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.Map;
import java.util.Objects;
import java.util.stream.Collectors;

@Data
@AllArgsConstructor
@NoArgsConstructor
public class DocumentExtractionResult {
    private Map<Integer, Page> pages;
    private Integer noOfPages;
    private AccountSummary accountSummary;
    private boolean isStatementWithReversedOrder;
    // this field indicate statement is in ascending order but transactions in particular date is in reverse
    private boolean isStatementWithReverseOrderPerDate;
    private PreProcessVerificationResult preProcessVerificationResult;
    private Integer transactionDateIndexByHeader;
    private Integer valueDateIndexByHeader;
    private Boolean bankSpecificProcessing = Boolean.FALSE;
    private BankSpecificStatementMetadata bankSpecificStatementMetadata;
    private boolean isStatementWithoutBalance;
    private boolean skipFurtherProcessing = false;
    private ExtractionPath extractionPath;
    private NativeTableExtractionPolicy nativePolicy;

    public DocumentExtractionResult copy() {
        Map<Integer, Page> copyPages = this.pages.entrySet().stream()
                .collect(Collectors.toMap(
                        Map.Entry::getKey,
                        entry -> entry.getValue().copy()
                ));


        return new DocumentExtractionResult(
            copyPages,
            this.noOfPages,
            this.accountSummary != null ? this.accountSummary.copy() : null,
            this.isStatementWithReversedOrder,
            this.isStatementWithReverseOrderPerDate,
            this.preProcessVerificationResult != null ? this.preProcessVerificationResult.copy() : null,
                this.transactionDateIndexByHeader,
                this.valueDateIndexByHeader,
                this.bankSpecificProcessing,
                this.bankSpecificStatementMetadata != null ? this.bankSpecificStatementMetadata.copy() : null,
                this.isStatementWithoutBalance,
                this.skipFurtherProcessing,
                this.extractionPath,
                this.nativePolicy
        );  
    }

    public DocumentExtractionResult copy(Integer numberOfPages) {
        Map<Integer, Page> filteredPages = this.pages.entrySet().stream()
                .filter(entry -> entry.getKey() <= numberOfPages)
                .collect(Collectors.toMap(
                        Map.Entry::getKey,
                    entry -> entry.getValue().copy()
                ));

        return new DocumentExtractionResult(
            filteredPages,
            Math.min(numberOfPages, filteredPages.size()),
            this.accountSummary != null ? this.accountSummary.copy() : null,
            this.isStatementWithReversedOrder,
            this.isStatementWithReverseOrderPerDate,
            this.preProcessVerificationResult != null ? this.preProcessVerificationResult.copy() : null,
                this.transactionDateIndexByHeader,
                this.valueDateIndexByHeader,
                this.bankSpecificProcessing,
                this.bankSpecificStatementMetadata != null ? this.bankSpecificStatementMetadata.copy() : null,
                this.isStatementWithoutBalance,
                this.skipFurtherProcessing,
                this.extractionPath,
                this.nativePolicy
        );
    }

    public DocumentExtractionResult copyOfPage(Integer pageNumber) {

        Map<Integer, Page> filteredPages = this.pages.entrySet().stream()
                .filter(entry -> Objects.equals(entry.getKey(), pageNumber))
                .collect(Collectors.toMap(
                        Map.Entry::getKey,
                        entry -> entry.getValue().copy()
                ));

        return new DocumentExtractionResult(
                filteredPages,
                Math.min(1, filteredPages.size()),
                this.accountSummary != null ? this.accountSummary.copy() : null,
                this.isStatementWithReversedOrder,
                this.isStatementWithReverseOrderPerDate,
                this.preProcessVerificationResult != null ? this.preProcessVerificationResult.copy() : null,
                this.transactionDateIndexByHeader,
                this.valueDateIndexByHeader,
                this.bankSpecificProcessing,
                this.bankSpecificStatementMetadata != null ? this.bankSpecificStatementMetadata.copy() : null,
                this.isStatementWithoutBalance,
                this.skipFurtherProcessing,
                this.extractionPath,
                this.nativePolicy
        );
    }

}

