private com.finboost.bank.statement.parser.representation.document.extraction.ExtractionPath resolveAccountExtractionPath(List<BankStatementVO> statements) {
    if (statements == null || statements.isEmpty()) {
        return null;
    }
    boolean anyNative = false;
    boolean anyMl = false;
    boolean anyFallback = false;
    for (BankStatementVO statement : statements) {
        if (statement.getExtractionPath() == null) {
            continue;
        }
        switch (statement.getExtractionPath()) {
            case NATIVE -> anyNative = true;
            case ML -> anyMl = true;
            case NATIVE_TO_ML_FALLBACK -> anyFallback = true;
        }
    }
    if (anyFallback || (anyNative && anyMl)) {
        return com.finboost.bank.statement.parser.representation.document.extraction.ExtractionPath.NATIVE_TO_ML_FALLBACK;
    }
    if (anyNative) {
        return com.finboost.bank.statement.parser.representation.document.extraction.ExtractionPath.NATIVE;
    }
    if (anyMl) {
        return com.finboost.bank.statement.parser.representation.document.extraction.ExtractionPath.ML;
    }
    return statements.get(0).getExtractionPath();
}

